using Microsoft.Win32;using System.Diagnostics;namespace Luma;public static class StartupManager{const string K=@"Software\Microsoft\Windows\CurrentVersion\Run";public static bool Enabled{get=>Registry.CurrentUser.OpenSubKey(K)?.GetValue("Luma")!=null;set{using var k=Registry.CurrentUser.CreateSubKey(K)!;if(value)k.SetValue("Luma",$"\"{Process.GetCurrentProcess().MainModule!.FileName}\" --background");else k.DeleteValue("Luma",false);}}}